// Agréger et résumer les news
const items = $input.all();

let cryptoNews = [];
let politiqueNews = [];

// Séparer les news par catégorie
for (const item of items) {
  const title = item.json.title || '';
  const link = item.json.link || '';
  const pubDate = item.json.pubDate || '';

  // Détection crypto (Bitcoin, BTC, crypto)
  if (title.toLowerCase().includes('bitcoin') || 
      title.toLowerCase().includes('btc') || 
      title.toLowerCase().includes('crypto')) {
    cryptoNews.push({ title, link, pubDate });
  }

  // Détection politique (government, regulation, fed, policy, ban, law)
  if (title.toLowerCase().includes('government') || 
      title.toLowerCase().includes('regulation') ||
      title.toLowerCase().includes('fed') ||
      title.toLowerCase().includes('policy') ||
      title.toLowerCase().includes('ban') ||
      title.toLowerCase().includes('law') ||
      title.toLowerCase().includes('president') ||
      title.toLowerCase().includes('congress')) {
    politiqueNews.push({ title, link, pubDate });
  }
}

// Créer un embed Discord riche
let embeds = [];

// Embed principal
let mainEmbed = {
  title: '📊 RÉSUMÉ NEWS DU JOUR',
  color: 3447003, // Bleu
  timestamp: new Date().toISOString(),
  footer: {
    text: 'Crypto & Politique News Alerts'
  },
  fields: []
};

// Ajouter les news crypto
if (cryptoNews.length > 0) {
  let cryptoText = '';
  cryptoNews.slice(0, 5).forEach((news, index) => {
    cryptoText += `**${index + 1}.** [${news.title}](${news.link})\n\n`;
  });
  mainEmbed.fields.push({
    name: '🪙 CRYPTO / BITCOIN',
    value: cryptoText || 'Aucune news',
    inline: false
  });
}

// Ajouter les news politique
if (politiqueNews.length > 0) {
  let politiqueText = '';
  politiqueNews.slice(0, 5).forEach((news, index) => {
    politiqueText += `**${index + 1}.** [${news.title}](${news.link})\n\n`;
  });
  mainEmbed.fields.push({
    name: '🏛️ POLITIQUE & RÉGULATION',
    value: politiqueText || 'Aucune news',
    inline: false
  });
}

// Stats
mainEmbed.fields.push({
  name: '📈 Statistiques',
  value: `🪙 ${cryptoNews.length} news crypto\n🏛️ ${politiqueNews.length} news politique`,
  inline: false
});

embeds.push(mainEmbed);

return [{ 
  json: { 
    embeds,
    content: '@everyone 📰 Voici votre résumé quotidien !',
    cryptoCount: cryptoNews.length, 
    politiqueCount: politiqueNews.length 
  } 
}];
